<?phpnamespace app\store\controller;use think\facade\Cache;/** * 插件控制器 */class Hemaphp extends Controller{    /**     * 安装方法     * @return bool     */    public static function install()    {        return true;    }    /**     * 卸载方法     * @return bool     */    public static function uninstall()    {        return true;    }		/**     * 升级方法     * @return bool     */    public static function upgrade()    {        Cache::clear(); //清空缓存        return true;    }}